import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { invoiceAPI } from '../services/api';
import { Card } from '../components/ui/Card';
import { usePageTitle } from '../hooks/usePageTitle';
import {
  FileText,
  CheckCircle,
  Clock,
  AlertCircle,
  Upload,
  List,
  ArrowRight,
  Sparkles,
} from 'lucide-react';

const formatCurrency = (amount) =>
  new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
  }).format(amount || 0);

const Dashboard = () => {
  usePageTitle('Dashboard');
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await invoiceAPI.getAnalytics();
        setAnalytics(res.analytics);
      } catch {
        setAnalytics(null);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const statCards = [
    {
      label: 'Total invoices',
      value: analytics?.totalInvoices ?? '—',
      icon: FileText,
      accent: 'bg-indigo-100 text-indigo-600',
    },
    {
      label: 'Avg. accuracy',
      value: analytics?.averageAccuracy != null ? `${analytics.averageAccuracy}%` : '—',
      icon: CheckCircle,
      accent: 'bg-emerald-100 text-emerald-600',
    },
    {
      label: 'Avg. processing',
      value: analytics?.averageProcessingTime != null ? `${analytics.averageProcessingTime} ms` : '—',
      icon: Clock,
      accent: 'bg-amber-100 text-amber-600',
    },
    {
      label: 'Unique vendors',
      value: analytics?.uniqueVendorsCount ?? '—',
      icon: AlertCircle,
      accent: 'bg-violet-100 text-violet-600',
    },
  ];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="mb-8">
        <p className="text-sm font-medium text-indigo-600 flex items-center gap-1.5">
          <Sparkles className="h-4 w-4" />
          Overview
        </p>
        <h1 className="mt-1 text-2xl font-bold tracking-tight text-gray-900">
          Dashboard
        </h1>
        <p className="mt-1 text-sm text-gray-600">
          AI-powered invoice capture, validation, and reporting in one place.
        </p>
      </div>

      {loading ? (
        <div className="flex justify-center py-24">
          <div className="h-10 w-10 rounded-full border-2 border-indigo-600 border-t-transparent animate-spin" />
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4 mb-8">
            {statCards.map(({ label, value, icon: Icon, accent }) => (
              <Card key={label} className="p-5">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <p className="text-sm font-medium text-gray-500">{label}</p>
                    <p className="mt-2 text-2xl font-semibold text-gray-900 tabular-nums">
                      {value}
                    </p>
                  </div>
                  <div className={`rounded-xl p-2.5 ${accent}`}>
                    <Icon className="h-5 w-5" />
                  </div>
                </div>
              </Card>
            ))}
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <Card className="p-6 lg:col-span-2">
              <h2 className="text-lg font-semibold text-gray-900">Total spending</h2>
              <p className="mt-4 text-4xl font-bold text-gray-900 tabular-nums">
                {analytics ? formatCurrency(analytics.totalAmount) : '—'}
              </p>
              <p className="mt-2 text-sm text-gray-500">
                Aggregated across all processed invoices.
              </p>
            </Card>

            <Card className="p-6 flex flex-col justify-between">
              <div>
                <h2 className="text-lg font-semibold text-gray-900">Quick actions</h2>
                <p className="mt-1 text-sm text-gray-500">
                  Jump to the tools you use most.
                </p>
              </div>
              <div className="mt-6 space-y-3">
                <Link
                  to="/upload"
                  className="flex items-center justify-between rounded-xl bg-indigo-600 px-4 py-3 text-sm font-medium text-white shadow-sm transition hover:bg-indigo-700"
                >
                  <span className="flex items-center gap-2">
                    <Upload className="h-4 w-4" />
                    Upload invoice
                  </span>
                  <ArrowRight className="h-4 w-4 opacity-80" />
                </Link>
                <Link
                  to="/invoices"
                  className="flex items-center justify-between rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm font-medium text-gray-800 shadow-sm transition hover:border-indigo-200 hover:bg-indigo-50/50"
                >
                  <span className="flex items-center gap-2">
                    <List className="h-4 w-4 text-indigo-600" />
                    View all invoices
                  </span>
                  <ArrowRight className="h-4 w-4 text-gray-400" />
                </Link>
              </div>
            </Card>
          </div>
        </>
      )}
    </div>
  );
};

export default Dashboard;
